import { course } from './build.js';
const GUIDE='https://hosa.org/wp-content/uploads/2026/08/MT-26-27.pdf';
const A='https://openstax.org/books/anatomy-and-physiology-2e/pages/';
const lessons=[];
function add(title,hook,sections,terms,caseStudy,questions,widget) {
 const glossary={t:'table',head:['Term','Meaning and distinction'],rows:terms.map(r=>r.slice(0,2))};
 const match={t:'w',kind:'match',title:'Connect the term to its meaning',pairs:terms.slice(0,5)};
 const sort={t:'w',kind:'sort',title:'Separate structures from findings and procedures',buckets:['Structure or word part','Finding or process','Procedure or discipline'],items:terms.map((r,i)=>[r[0],r[2]??0])};
 const mcqs=questions.concat(terms.slice(0,8-questions.length).map((r,i)=>[`Which description correctly identifies ${r[0]}?`,[r[1],...terms.filter((_,j)=>j!==i).slice(0,3).map(x=>x[1])],r[1]]));
 lessons.push({title,hook,objectives:[`Decode the principal vocabulary of ${title.toLowerCase()}.`,'Explain how word parts connect to anatomy and function.','Distinguish look-alike terms and interpret a clinical statement without adding unsupported meaning.'],sections:[...sections.map(([h,p])=>[h,Array.isArray(p)?p:[p]]),['Vocabulary in context',[glossary,match,widget||sort]],['Apply the language',[{t:'example',prompt:caseStudy[0],steps:caseStudy[1],answer:caseStudy[2]}]]],terms:terms.map(t=>t.slice(0,2)),takeaways:terms.slice(0,3).map(t=>`${t[0]}: ${t[1]}`),mcqs,frq:{prompt:caseStudy[0]+' Explain the important distinctions and state what cannot be concluded from the terms alone.',rubric:caseStudy[3],model:caseStudy[1].join(' ')+' '+caseStudy[2]},sources:[['HOSA Medical Terminology 2026–27 guidelines and official textbooks',GUIDE],['OpenStax Anatomy and Physiology 2e: anatomical terminology',A+'1-6-anatomical-terminology'],['MedlinePlus: understanding medical words','https://medlineplus.gov/medwords/'] ]});
}

add('Respiratory passages, gas exchange, and breathing findings','Dyspnea, tachypnea, and hypoxemia can occur together, but they do not mean the same thing. One describes the experience of breathing, another its rate, and another oxygen in the blood.',[
 ['Airway anatomy provides the map','Rhin/o identifies nose, sinus/o a sinus, pharyng/o pharynx, laryng/o larynx, trache/o trachea, and bronch/o bronchus. Air travels through conducting passages toward smaller bronchioles and alveoli. The pharynx is shared by respiratory and digestive pathways, while the larynx contains structures important for voice and airway protection. The trachea divides into main bronchi, which branch within the lungs. Alveol/o refers to alveoli, the small air spaces where gas exchange occurs. Pneum/o can refer to air or lung depending on the word, while pulmon/o refers to lung. The pleura covers the lungs and lines the thoracic wall. Do not confuse the pleural space with the alveolar air spaces; air in the pleural space has a very different significance.'],
 ['Movement of air is not the same as exchange','Ventilation is movement of air into and out of lungs. Inspiration brings air inward and expiration moves it outward. Diffusion moves oxygen and carbon dioxide across the alveolar-capillary interface, while perfusion supplies blood to that interface. Respiration can refer broadly to gas exchange and cellular processes, so context matters. Hypoventilation means ventilation is insufficient relative to metabolic carbon dioxide production, not merely that breaths look slow. Hyperventilation means ventilation exceeds that requirement and tends to reduce carbon dioxide. A fast respiratory rate alone is tachypnea, and it does not prove hyperventilation. Shallow rapid breaths can move less effective alveolar air than the rate suggests. Separate frequency, depth, exchange, and circulation when describing function.'],
 ['Breathing symptoms and signs','Dyspnea is difficult or uncomfortable breathing experienced by the person. Apnea is absence of breathing for a period. Orthopnea is breathlessness when lying flat, while tachypnea and bradypnea describe fast and slow rates. Hypoxemia means low arterial blood oxygen; hypoxia means inadequate oxygen at tissue level. Hypercapnia means increased carbon dioxide in blood. Cyanosis describes bluish coloration and is not a substitute for measuring oxygenation. Hemoptysis is coughing up blood from the respiratory tract, distinct from hematemesis, vomiting blood. Stridor is a high-pitched sound associated with upper-airway narrowing, whereas wheezing often reflects airflow through narrowed lower airways. These terms guide communication but do not independently establish a single diagnosis or treatment.'],
 ['Conditions and procedures share roots but differ in category','Bronchitis means bronchial inflammation, and pleuritis pleural inflammation. Pneumonia is an infection-related inflammatory disease of lung tissue rather than a generic term for every breathing difficulty. Pneumothorax means air in the pleural space; hemothorax means blood there. Atelectasis refers to incomplete expansion or collapse of lung tissue. A tracheotomy is an incision into the trachea, while tracheostomy refers to creation of an opening into it. Bronchoscopy is visual examination of airways using an instrument. Thoracentesis is puncture into the pleural space to withdraw material, usually fluid in its common clinical use. Spirometry measures aspects of air movement and volumes. Do not infer that a procedure found an abnormality merely because it was performed.'],
 ['Read a respiratory sentence in layers','Consider a report of tachypnea, dyspnea, and a planned chest radiograph. Tachypnea describes an observed rate, dyspnea a reported experience, and radiography an imaging process. The statement does not confirm pneumonia, pulmonary embolism, asthma, or another cause. A respiratory therapist works with breathing assessment and support within professional scope, while a pulmonologist is a physician specializing in respiratory disease. The names of these roles should be linked to function without assuming that every professional performs every procedure. For study, trace the airway with roots, then attach terms for inflammation, examination, and abnormal findings. Finally compare pairs that look interchangeable but measure different things. A good explanation of hypoxia versus hypoxemia identifies the tissue versus blood distinction rather than merely saying both involve low oxygen.']
],[['Alveolus','A small lung air space involved in gas exchange. It is different from the pleural space, which is associated with the lung’s external covering.',0],['Tachypnea','A rapid breathing rate relative to context. It does not by itself establish whether effective ventilation is excessive or adequate.',1],['Dyspnea','The experience of difficult or uncomfortable breathing. It is a symptom and can occur through many different physiological mechanisms.',1],['Hypoxemia','Reduced arterial blood oxygen. The term specifies blood rather than directly describing oxygen availability within every tissue.',1],['Hypercapnia','Increased carbon dioxide in blood. It is a separate variable from oxygen concentration and should not be treated as a synonym for hypoxemia.',1],['Pneumothorax','Air within the pleural space. The prefix and root identify air and thorax, but the accepted definition specifies the location more precisely.',1],['Bronchoscopy','Instrument-assisted visual examination of the airways. The name identifies an examination, while results require separate documentation.',2],['Thoracentesis','Puncture into the pleural space to withdraw material. It differs from a surgical incision and from visual examination of the bronchi.',2]],['A person is described as tachypneic and dyspneic, with hypoxemia. Explain all three without treating them as synonyms, and identify information still needed to determine the cause.',['Tachypnea identifies an increased rate, while dyspnea identifies the experience of breathing discomfort.','Hypoxemia identifies reduced oxygen in arterial blood.','History, examination, and appropriate investigations are needed to determine why these findings occur.'],'The combination indicates related but distinct observations. It does not by itself prove a particular disease, nor does rapid breathing guarantee adequate alveolar ventilation.',[['Rate',['rate','rapid','tachypnea']],['Experience',['discomfort','dyspnea','difficult']],['Blood oxygen and uncertainty',['arterial','oxygen','cause']]]],[['Which term means coughing up blood?',['Hemoptysis','Hematemesis','Hematuria','Melena'],'Hemoptysis concerns the respiratory tract.'],['Air in the pleural space is called what?',['Pneumothorax','Bronchitis','Rhinitis','Hypercapnia'],'Pneumothorax specifies air outside the lung in the pleural space.']]);

add('Digestive and urinary pathways: similar words, different routes','Ureter and urethra differ by a few letters but connect different locations. Tracing a substance through the body gives each word a place and makes these distinctions easier to remember.',[
 ['Digestive structures and accessory organs','The digestive tract includes mouth, pharynx, esophagus, stomach, small intestine, and large intestine. Stomat/o and or/o relate to mouth, gloss/o and lingu/o to tongue, esophag/o to esophagus, gastr/o to stomach, enter/o to intestine, and col/o to colon. The small intestine includes duodenum, jejunum, and ileum. The large intestine includes cecum and colon before the rectum and anal canal. Hepat/o identifies liver, cholecyst/o gallbladder, chol/e bile, and pancreat/o pancreas. These accessory organs contribute secretions or metabolic functions without being sections that swallowed food normally passes through. A gallbladder is not a kidney or urinary bladder. The presence of the syllable bladder does not make all three structures part of the same system.'],
 ['Digestive findings and procedure endings','Dysphagia means difficulty swallowing, while dyspepsia describes indigestion. Emesis means vomiting; hematemesis is vomiting blood. Melena describes black, tarry stool associated with digested blood, while hematochezia refers to passage of fresh blood through the anus. These terms describe patterns and require clinical interpretation. Diarrhea concerns loose or watery stools, and constipation concerns difficult or infrequent passage according to context. Hepatomegaly is liver enlargement, cholelithiasis the presence of gallstones, and pancreatitis pancreatic inflammation. Colonoscopy examines the colon visually, while colectomy removes part or all of it. A colostomy creates an opening from colon to the body surface. The shared col/o root remains stable while each suffix changes what is being described.'],
 ['The urinary route and kidney organization','Nephr/o and ren/o refer to kidney. Pyel/o refers to the renal pelvis, ureter/o to ureter, cyst/o often to bladder, and urethr/o to urethra. Urine formed by kidneys passes through renal collecting structures and pelvis, then ureters, bladder, and urethra. The nephron is a functional kidney unit involved in filtration and modification of fluid. Glomerul/o refers to the glomerulus, the capillary structure associated with filtration. The kidney cortex and medulla are regions, not separate organs. A ureter is a transport tube from kidney to bladder; the urethra transports urine outward from the bladder. Trace the pathway before interpreting a compound term such as ureterolithiasis. The location of a stone affects the meaning even though the suffix -lithiasis remains the same.'],
 ['Volume, frequency, contents, and symptoms','Polyuria means increased urine volume, whereas frequent urination can involve many small voids without high total volume. Oliguria is reduced output and anuria essentially absent output in the relevant clinical definition. Dysuria means painful or difficult urination; nocturia means waking to urinate during the sleep period. Hematuria is blood in urine, proteinuria protein in urine, and glycosuria glucose in urine. The -uria ending does not mean infection. Cystitis means bladder inflammation, nephritis kidney inflammation, and pyelonephritis refers to infection-related inflammation involving kidney and renal pelvis. Incontinence means loss of voluntary control of elimination in context; retention means inability to empty adequately. A person can have both retention and overflow leakage, showing why a symptom description does not always reveal the mechanism.'],
 ['Examination, removal, and renal specialties','Cystoscopy is visual examination of the bladder, nephrectomy removal of kidney tissue, and lithotripsy fragmentation of stones. Dialysis is a process of separating substances across a membrane in clinical renal replacement contexts; it is not synonymous with restoring normal kidney anatomy. A nephrologist focuses on kidney medicine, while a urologist addresses the urinary tract and related surgical and reproductive conditions. Urinalysis examines urine using several types of observations and tests; it is not one single measurement. A statement of proteinuria reports a finding but not its cause or permanence. Compare digestive and urinary words explicitly: dysphagia concerns swallowing, dysuria urination; hematemesis concerns vomit, hematuria urine. Strong terminology knowledge preserves both the named substance and the pathway through which it appears.']
],[['Hepat/o','The liver combining form. It differs from cholecyst/o for gallbladder and gastr/o for stomach, even though all participate in digestive physiology.',0],['Dysphagia','Difficulty swallowing. It refers to the swallowing process rather than painful urination, indigestion, or the amount of urine produced.',1],['Hematemesis','Vomiting blood. The route of blood appearance distinguishes it from coughing blood or passing blood in urine.',1],['Ureter','The tube carrying urine from a kidney toward the bladder. There are normally two, corresponding to the two kidneys.',0],['Urethra','The outlet carrying urine from bladder toward the exterior. It is a different structure from either ureter.',0],['Polyuria','Increased total urine volume. It should not be equated automatically with frequency, because frequent voiding can involve small amounts.',1],['Proteinuria','Protein present in urine beyond the relevant expected level. It is a finding requiring interpretation, not an automatic diagnosis of one specific disease.',1],['Lithotripsy','A procedure that fragments stones. The complete context identifies the stone location and technique rather than the suffix alone.',2]],['A learner confuses dysphagia with dysuria and interprets frequent small voids as polyuria. Correct the terms and trace urine from kidney to exterior.',['Dysphagia means difficulty swallowing; dysuria means painful or difficult urination.','Polyuria concerns total urine volume, so frequency alone does not establish it.','Urine moves from kidney through ureter to bladder and then through urethra outward.'],'The corrected explanation separates function, quantity, and location. Additional measurements would be needed to establish total output or the reason for symptoms.',[['Distinguishes symptoms',['swallow','urinat','dys']],['Volume versus frequency',['volume','frequency','small']],['Correct urinary route',['ureter','bladder','urethra']]]],[['Which procedure visually examines the colon?',['Colonoscopy','Colectomy','Colostomy','Cholecystectomy'],'-scopy identifies visual examination and col/o identifies colon.'],['Which term indicates blood in urine?',['Hematuria','Hematemesis','Hemoptysis','Hepatomegaly'],'Hematuria combines blood-related meaning with a urine condition.']]);

add('Nervous-system and special-sense vocabulary','Aphasia, paresis, and paresthesia may appear in the same neurological record. They concern language, strength, and sensation respectively. Similar-looking words should not erase different functions.',[
 ['Central and peripheral pathways','The central nervous system comprises brain and spinal cord; peripheral nerves connect it with the rest of the body. Encephal/o means brain, cerebr/o cerebrum, cerebell/o cerebellum, neur/o nerve, and mening/o meninges. Myel/o can identify spinal cord in neurological terms, but bone marrow in hematological terms. The meninges are protective membranes rather than nerve cells. A neuron transmits information, while neuroglia provide several supporting and regulatory functions. Afferent pathways carry information toward the central nervous system and efferent pathways carry output away. Somatic pathways support body-wall sensation and skeletal-muscle control; autonomic pathways regulate many internal functions. Sympathetic and parasympathetic divisions have distinct but coordinated effects. Avoid treating sympathetic as always harmful or parasympathetic as always beneficial.'],
 ['Language, sensation, movement, and cognition','Aphasia is impaired language function and can involve expression, comprehension, or both. Dysarthria concerns impaired articulation of speech due to motor control, so a person may understand language while having difficulty producing clear sounds. Paresthesia is abnormal sensation such as tingling; anesthesia can mean loss of sensation in a region or a clinical state produced for procedures. Neuralgia means nerve-related pain, while neuropathy means nerve disorder. Paresis is weakness, paralysis loss of motor function, and ataxia impaired coordination. Amnesia concerns memory loss, not every form of cognitive impairment. These categories help describe which function is affected. A neurological symptom does not alone localize the exact lesion or prove its cause, so precision includes avoiding a diagnosis unsupported by the record.'],
 ['Disorders and diagnostic procedures','Meningitis is inflammation of the meninges, encephalitis of brain tissue, and myelitis of spinal cord in this context. The suffix identifies inflammation, but established definitions and evidence determine cause. Hydrocephalus involves abnormal accumulation of cerebrospinal fluid within ventricular spaces. Electroencephalography records brain electrical activity; an electroencephalogram is its record. A lumbar puncture accesses the subarachnoid space in the lower back for specified diagnostic or therapeutic purposes. Computed tomography and magnetic resonance imaging use different physical methods and are not interchangeable abbreviations for any brain scan. A neurologist specializes in nervous-system disorders; a neurosurgeon addresses selected disorders surgically. A test’s name does not tell you the result, and an ordered test does not prove the disease it is intended to investigate.'],
 ['The eye and visual terminology','Ophthalm/o and ocul/o refer to eye, opt/o to vision, retin/o to retina, irid/o to iris, and kerat/o may refer to cornea in ophthalmic context. The cornea is an anterior transparent surface; the lens focuses light; the retina contains sensory cells; and the optic nerve carries signals centrally. Conjunctiva covers portions of the anterior eye and inner eyelids. Conjunctivitis is not synonymous with every red eye. Myopia is nearsightedness, hyperopia farsightedness, diplopia double vision, and photophobia discomfort with light. Cataract is lens opacity, while glaucoma involves optic-nerve damage and is often associated with intraocular pressure. These disorders involve different structures. An ophthalmologist is a physician specializing in eye care, while optometry is a distinct profession with jurisdiction-dependent scope.'],
 ['Hearing, balance, and integrated interpretation','Ot/o identifies ear, tympan/o the tympanic membrane or middle-ear context, audi/o hearing, and vestibul/o the vestibular system in relevant terms. The outer ear conducts sound toward the tympanic membrane; middle-ear ossicles transmit vibration; inner-ear structures support hearing and balance. Otitis media concerns the middle ear, while otitis externa concerns the external ear canal. Tinnitus is perception of sound without an external source. Vertigo is an illusion of movement and differs from nonspecific lightheadedness. Audiometry measures hearing, while an audiogram records results. A case may combine hearing loss with vertigo, but the pairing does not automatically establish a single cause. Translate the sensory domain first, then identify whether the word describes structure, subjective experience, measured impairment, or procedure.']
],[['Afferent','Carrying information toward the central nervous system. Sensory pathways are commonly described this way, in contrast to efferent output.',0],['Aphasia','Impaired language function, potentially affecting comprehension or expression. It is different from impaired articulation caused by speech-muscle control.',1],['Paresthesia','An abnormal sensation such as tingling. The term does not establish weakness, a specific nerve lesion, or the underlying cause.',1],['Ataxia','Impaired coordination. It is not simply another name for pain or reduced muscle strength.',1],['Electroencephalogram','A record of brain electrical activity. It differs from structural imaging and from the process called electroencephalography.',2],['Cataract','Opacity of the eye’s lens. It involves a different structure and mechanism from optic-nerve injury in glaucoma.',1],['Diplopia','Double vision, a symptom requiring further assessment. The word itself does not identify which structure or pathway is responsible.',1],['Vertigo','An illusion of movement, often described as spinning. It is more specific than the broad everyday word dizziness.',1]],['A record describes aphasia, paresthesia, and diplopia. Translate the three findings and explain why none is synonymous with paralysis.',['Aphasia affects language, paresthesia sensation, and diplopia visual perception.','Paralysis concerns loss of motor function rather than these three domains.','The findings require further neurological and clinical interpretation to determine location and cause.'],'A precise summary preserves the affected functions and avoids converting a symptom list into an unreported diagnosis.',[['Language',['aphasia','language']],['Sensation and vision',['tingl','sensation','double','vision']],['Motor distinction and limits',['motor','paralysis','cause']]]],[['Which term means impaired speech articulation rather than language processing?',['Dysarthria','Aphasia','Amnesia','Diplopia'],'Dysarthria concerns motor production of speech.'],['Which structure carries visual signals from the eye centrally?',['Optic nerve','Lens','Conjunctiva','Tympanic membrane'],'The optic nerve conveys retinal output toward the brain.']]);

add('Endocrine and reproductive language in clinical context','A hysterectomy does not by definition remove the ovaries, and diabetes insipidus is not another name for diabetes mellitus. Shared roots and familiar labels must be checked against anatomy and accepted definitions.',[
 ['Hormones, glands, and feedback','Endocrine glands release hormones into circulation, while exocrine glands release products through ducts. Thyroid/o refers to thyroid, parathyroid/o to parathyroid, adren/o to adrenal gland, and pituitar/o to pituitary. Pancreat/o refers to a gland with both endocrine and exocrine functions. A hormone is a signaling molecule, and a target tissue has the relevant machinery to respond. Tropic hormones influence other endocrine glands. Negative feedback restrains an upstream signal when downstream output is adequate. A name such as hyperthyroidism describes excessive thyroid hormone activity, while hypothyroidism describes insufficient activity. The name identifies a functional direction, not necessarily the exact lesion or cause. Distinguish the gland’s anatomy from a hormone it secretes and from the physiological effect of that hormone.'],
 ['Endocrine findings and misleading similarities','Hyperglycemia means elevated blood glucose and hypoglycemia reduced blood glucose. Glycosuria means glucose in urine, a different compartment. Polyuria is increased urine volume and polydipsia increased thirst. Diabetes mellitus concerns glucose regulation, while diabetes insipidus concerns water-balance regulation and has a distinct mechanism. Similar symptoms do not make the disorders identical. Goiter is thyroid enlargement and can occur with different functional states, so the word does not automatically mean hyperthyroidism. Acromegaly involves enlargement of acral and other tissues associated with excess growth-hormone activity after growth-plate closure. Adrenal cortex and medulla are different regions with different secretions. Terminology should help organize those differences, not replace the physiological understanding needed to interpret them.'],
 ['Female reproductive structures and procedures','Hyster/o and uter/o identify uterus, oophor/o ovary, salping/o tube in relevant gynecological terms, cervic/o uterine cervix or neck depending on context, and colp/o vagina. Mamm/o and mast/o refer to breast. The uterus, ovaries, and uterine tubes are separate structures with different functions. Hysterectomy means removal of uterine tissue; oophorectomy removal of an ovary; salpingectomy removal of a uterine tube. Bilateral salpingo-oophorectomy identifies removal of both tubes and ovaries. Do not add organ removal that the name does not specify. Endometrium is the uterine inner lining, myometrium its muscular wall, and endometriosis refers to endometrial-like tissue outside the uterus. A literal suffix reading alone is insufficient to define every established disease term correctly.'],
 ['Male reproductive and pregnancy terminology','Orchid/o and orchi/o identify testis, epididym/o epididymis, prostat/o prostate, and balan/o glans in relevant terms. Spermat/o relates to sperm. The testes produce sperm and hormones; the prostate contributes to seminal fluid but is not the organ that produces sperm. Prostatitis is prostate inflammation, while prostate enlargement is not automatically cancer. Obstetrics concerns pregnancy and childbirth, while gynecology concerns the female reproductive system more broadly. Prenatal means before birth, intrapartum during labor or delivery, and postpartum after childbirth. Gravida refers to pregnancies and para to births meeting the relevant clinical definition; exact recording conventions should be checked in the assigned reference. A gestational label is not equivalent to a patient’s current number of living children.'],
 ['Integration, specialists, and accurate summaries','An endocrinologist specializes in hormone-related disorders, an obstetrician in pregnancy and childbirth care, and a gynecologist in female reproductive care. A urologist addresses urinary and selected reproductive conditions. A biopsy obtains tissue for examination; cytology examines cells, and histology tissues. Screening for a disease is not confirmation of it. When a record combines anatomy, procedure, and findings, preserve each category. A person may have a hysterectomy with ovaries retained; that description should not be rewritten as removal of all reproductive organs. Likewise, a thyroid nodule is a structural finding, while hormone measurements assess function. The most reliable final review joins word parts, anatomy, function, and context. State what the word means, identify a contrasting term, and note which clinical questions remain unanswered.']
],[['Endocrine','Hormone secretion into circulation rather than through an exocrine duct. A gland can have both endocrine and exocrine components, as the pancreas does.',0],['Hyperglycemia','Elevated blood glucose. It names the direction and compartment of the finding, but does not independently determine its cause or treatment.',1],['Goiter','Enlargement of the thyroid gland. It describes anatomy and can occur with different levels of hormone function.',1],['Hysterectomy','Surgical removal of the uterus or specified uterine tissue. Removal of ovaries must be stated separately rather than assumed.',2],['Oophorectomy','Surgical removal of an ovary. Bilateral specifies both ovaries, while the basic term alone does not determine laterality.',2],['Myometrium','The muscular wall of the uterus. It differs from the endometrial lining and from tissues outside the uterus.',0],['Postpartum','After childbirth. It is a timing descriptor and does not by itself identify a disorder or the person’s recovery status.',1],['Prostatitis','Inflammation of the prostate. The term should not be exchanged with benign enlargement or prostate cancer.',1]],['Explain why hysterectomy does not automatically mean oophorectomy, and why goiter does not automatically mean hyperthyroidism.',['The uterus and ovaries are separate organs with separate removal terms.','Goiter describes thyroid enlargement, while hyperthyroidism describes excessive hormone activity.','A structural description does not independently establish function, cause, or the extent of a procedure.'],'Accurate interpretation requires the complete procedure description and relevant assessment. Preserving anatomy and function as separate categories prevents adding facts absent from the record.',[['Distinct organs',['uterus','ovary','ovaries']],['Structure versus function',['enlarge','hormone','goiter']],['Avoids unsupported inference',['not','extent','assessment','separate']]]],[['Which gland has both endocrine and exocrine functions?',['Pancreas','Thyroid only','Parathyroid only','Pituitary only'],'The pancreas releases hormones to blood and digestive secretions through ducts.'],['Which term means increased thirst?',['Polydipsia','Polyuria','Glycosuria','Dysphagia'],'Polydipsia describes thirst; polyuria describes urine volume.']]);

lessons.find(l=>l.title.startsWith('Word roots')).sections[0][1].push({t:'w',kind:'termlab',title:'Take a medical word apart'});
export default course('Medical Terminology',{intro:'Ten connected lessons cover the 2026–27 word-part and body-system blueprint. Build, compare, and translate medical language, then apply it in a written-response checkpoint. Use the official references for authoritative definitions and spelling.',units:[{title:'Unit 1 · Build precise medical language',summary:'Roots, prefixes, suffixes, spelling, and body orientation.',lessons:[lessons.find(l=>l.title.startsWith('Word roots')),lessons.find(l=>l.title.startsWith('Prefixes')),lessons.find(l=>l.title.startsWith('Anatomical'))]},{title:'Unit 2 · Support, movement, and circulation',summary:'Skin, skeleton, muscle, blood, and lymphatic terminology.',lessons:lessons.filter(l=>/^(Skin|Muscle|Cardiovascular)/.test(l.title))},{title:'Unit 3 · Exchange and elimination',summary:'Respiratory, digestive, and urinary pathways.',lessons:lessons.filter(l=>/^(Respiratory|Digestive)/.test(l.title))},{title:'Unit 4 · Regulation, senses, and reproduction',summary:'Neural, endocrine, and reproductive vocabulary in context.',lessons:lessons.filter(l=>/^(Nervous|Endocrine)/.test(l.title))}]});

add('Skin, membranes, and skeletal terminology','A referral mentions erythema, an abrasion, and a possible fracture. Each word describes a different category of finding. The language of skin and bone becomes clearer when structure and damage are separated.',[
 ['Skin layers and combining forms','Dermat/o and derm/o refer to skin, while cutane/o is another skin-related form. The epidermis is the outer epithelial layer. The dermis beneath it contains connective tissue, blood vessels, glands, and sensory structures. Subcutaneous tissue lies beneath the skin and includes variable amounts of fat and connective tissue. A transdermal route crosses the skin, while an intradermal route is within its dermal layer. Seb/o relates to sebum, hidr/o to sweat, trich/o to hair, and onych/o to nail. These forms help distinguish the affected accessory structure. A nail disorder is not automatically a hair disorder simply because both structures contain keratin. Use layer names to locate a finding, then use a suffix to identify the process. Dermatitis names inflammation, whereas dermatoplasty names repair.'],
 ['Describe a lesion before naming a cause','A macule is a flat area of altered color; a papule is a small solid elevation; a vesicle contains fluid; and a pustule contains purulent material. A nodule is a deeper solid lesion. An abrasion is superficial scraping, a laceration a tear, and an ulcer a loss of surface tissue with greater depth. Erythema means redness, ecchymosis bruising, and cyanosis a bluish discoloration. These descriptions are not interchangeable diagnoses. Redness may accompany inflammation, heat, or other processes, and a vesicle does not identify a particular virus by itself. Describe size, location, distribution, and appearance where provided. Do not introduce a cause that the question never states. The distinction between morphology and etiology is a recurring test of medical-language precision.'],
 ['Bone and joint architecture','Oste/o refers to bone, chondr/o to cartilage, arthr/o to joint, and myel/o may refer to marrow in skeletal terms. The skeleton includes axial structures such as skull, vertebral column, and rib cage, and appendicular structures such as limbs and their girdles. A long bone has a diaphysis or shaft and epiphyses at its ends. The periosteum covers external bone surfaces except where articular cartilage is present. Compact bone is dense, while spongy bone has a trabecular architecture. Bone marrow occupies internal spaces and is distinct from the mineralized matrix. A ligament commonly connects bone to bone; a tendon connects muscle to bone. Confusing these attachments changes the meaning of a soft-tissue injury.'],
 ['Disorders and procedures are separate word families','Osteoporosis concerns reduced bone strength and increased fracture risk, while osteomalacia concerns defective mineralization. Osteomyelitis is infection-associated inflammation of bone and marrow; the established definition is more specific than merely reading each root. Arthritis means joint inflammation, but osteoarthritis and rheumatoid arthritis have distinct mechanisms. Arthralgia means joint pain without specifying inflammation. Ankylosis describes stiffness or fusion of a joint. Arthroscopy is visual examination of a joint, arthroplasty repair or replacement, and arthrocentesis puncture to remove joint fluid. A fracture is a break in bone; an open fracture communicates with the external environment through a wound. Open does not mean that the broken bone must visibly protrude. Accurate definitions prevent intuitive but incorrect conclusions.'],
 ['Clinical description and occupations','A dermatologist specializes in skin disorders, while orthopedic practice addresses the musculoskeletal system. A pathologist may examine tissue to help determine disease, and a radiologist interprets imaging. Their names identify roles, not guarantees about a specific procedure in every encounter. When a record combines terms, translate one layer at a time: location, structure, finding, and procedure. A superficial abrasion over the patella describes a skin injury over the anterior knee region; it does not establish a patellar fracture. Imaging or further assessment would address the bone question. Similarly, edema is swelling from fluid accumulation and can accompany many different conditions. Avoid turning a descriptive term into a definitive diagnosis. A precise student can explain both what a word tells the reader and what it leaves unresolved.']
],[['Epidermis','The outer epithelial skin layer, distinct from the deeper vascular connective tissue of the dermis. The term locates a layer rather than naming a disease.',0],['Vesicle','A small fluid-filled skin lesion. Its appearance does not independently identify whether the cause is infectious, inflammatory, or another process.',1],['Erythema','Redness of skin or mucosa. It is a descriptive finding and should not automatically be translated as infection.',1],['Oste/o','A combining form meaning bone. It differs from chondr/o for cartilage and arthr/o for joint, even though those tissues work together.',0],['Diaphysis','The shaft of a long bone. It is anatomically distinct from the epiphyses at the ends and the periosteal covering.',0],['Arthralgia','Joint pain. The word names a symptom and does not by itself prove inflammatory arthritis or identify the cause.',1],['Arthrocentesis','Puncture of a joint to withdraw fluid. It is a procedure that may provide diagnostic material or serve another clinical purpose.',2],['Arthroscopy','Instrument-assisted visual examination of a joint. Findings and any additional treatment must be described separately from the procedure name.',2]],['A note says erythema and a vesicle over the patella with arthralgia. Translate the findings, separate skin from joint vocabulary, and explain why infection is not proven.',['Erythema means redness, and a vesicle is a fluid-filled skin lesion.','Patella locates the kneecap region; arthralgia means joint pain.','The descriptors do not establish whether the skin and joint findings share a cause.'],'Further history and examination are needed to determine etiology. Translating each term accurately preserves the distinction between observed skin appearance, an anatomical landmark, and a reported symptom.',[['Translates skin findings',['red','fluid','vesicle']],['Identifies structure and symptom',['patella','joint','pain']],['Avoids unsupported cause',['cause','infection','not']]]],[['Which form identifies cartilage?',['Chondr/o','Oste/o','Dermat/o','Hidr/o'],'Chondr/o identifies cartilage rather than bone, skin, or sweat.'],['What connects muscle to bone?',['Tendon','Ligament in its usual joint role','Epidermis','Marrow'],'Tendons transmit muscle force to bone.']]);

add('Muscle, movement, and functional impairment','Two patients have difficulty walking: one has myalgia, while another has ataxia. The words point to pain in one case and coordination in the other. Function must be described precisely before its cause is considered.',[
 ['Muscle tissues and their language','My/o and myos/o refer to muscle. Skeletal muscle generally produces voluntary movement, cardiac muscle forms the heart’s pumping tissue, and smooth muscle controls many hollow-organ walls and vessels. Rhabdomy/o refers to striated skeletal muscle, while leiomy/o refers to smooth muscle. A myocyte is a muscle cell. Myofibrils contain contractile components, and fascia is connective tissue surrounding and separating structures. A tendon links muscle to bone, while an aponeurosis is a broad sheet-like tendon. These words describe different levels of organization. Myocardium is heart muscle, not the entire heart and not the membrane around it. In a compound word, identify both the tissue and the organ-specific modifier. This prevents myel/o, my/o, and myocard/o from becoming one indistinct group in memory.'],
 ['Movement pairs and reference axes','Flexion generally decreases the angle at a joint, and extension increases it. Abduction moves a body part away from the relevant midline; adduction moves it toward that line. For fingers and toes, the reference axis is defined within the hand or foot rather than always being the trunk’s midline. Rotation turns a structure around an axis. Circumduction combines movements so the distal end traces a cone. Pronation and supination describe rotation of the forearm and hand; supination turns the palm anteriorly in anatomical position. Dorsiflexion brings the top of the foot toward the shin, while plantar flexion points the foot downward. Learn movements with a harmless demonstration or drawing, but do not assume every joint can perform every listed movement. Joint structure limits its available motion.'],
 ['Symptoms, weakness, and loss of function','Myalgia means muscle pain. Myositis means inflammation of muscle, and myopathy means muscle disease. These terms are related but not synonymous. Paresis means partial weakness, whereas paralysis refers to loss of voluntary motor function to a degree defined in the clinical context. Hemiparesis affects one side, paraparesis both lower limbs, and quadriparesis all four limbs. Ataxia means impaired coordination and can occur without primary loss of muscle strength. Spasticity describes a particular increase in muscle tone associated with neurological dysfunction; it is not simply any painful muscle spasm. A contracture is a persistent shortening or limitation of soft tissue and joint movement. Distinguish a patient’s experience of pain from a measured limitation in range, strength, or coordination.'],
 ['Adaptation, injury, and diagnostic language','Hypertrophy is enlargement of cells and can increase muscle size. Atrophy is reduction in tissue size, often associated with disuse or disease. Hyperplasia is increased cell number, so it should not be used casually as a synonym for muscle enlargement. A strain involves injury to muscle or tendon, while a sprain concerns a ligament. Tendinitis refers to tendon inflammation; tendinopathy is a broader term for tendon disorder. Electromyography records muscle electrical activity, and an electromyogram is the resulting record. Range of motion describes movement available at a joint, while manual muscle testing estimates strength using an organized assessment. Neither term alone is a treatment. Rehabilitation professions may use these measures, but the vocabulary should not imply that a student is qualified to perform a clinical assessment independently.'],
 ['Use context to translate a functional report','Consider a report of right hemiparesis with limited shoulder abduction. Hemiparesis identifies weakness on one side, and right specifies the patient’s side. Abduction identifies movement away from the midline, while shoulder identifies the joint. The statement does not tell you whether pain, neurological injury, joint restriction, or several factors contribute to the limited movement. It also does not prove that the shoulder muscle itself is diseased. This is why symptoms and findings should remain distinct from causation. In study practice, ask what the term classifies: tissue, movement, symptom, impairment, test, or professional role. Then add a concrete example. Translating entire phrases builds stronger understanding than memorizing isolated suffixes without seeing the relationship between anatomy and function.']
],[['Myalgia','Muscle pain, a symptom rather than proof of inflammation. The cause can involve many processes and requires information beyond the suffix -algia.',1],['Myopathy','A disorder of muscle. It is broader than a specific inflammatory condition and does not identify a single cause or severity.',1],['Abduction','Movement away from a reference midline or axis. The appropriate reference depends on the body part, especially for digits.',1],['Adduction','Movement toward a reference midline or axis. It is the contrasting movement to abduction, not a synonym for flexion.',1],['Paresis','Partial weakness or incomplete loss of motor power. Prefixes can identify the distribution, such as hemi- for one side.',1],['Ataxia','Impaired coordination of movement. A person can have ataxia without the same pattern of primary muscle weakness as paresis.',1],['Electromyography','The process of recording muscle electrical activity. The -graphy ending identifies the recording process rather than the record itself.',2],['Contracture','Persistent shortening or restriction of tissue that limits movement. It differs from a brief, transient muscle contraction during normal activity.',1]],['A report describes myalgia, reduced shoulder abduction, and an ordered electromyogram. Explain the symptom, movement, and diagnostic term, including what is not yet known.',['Myalgia identifies muscle pain but not its cause.','Shoulder abduction moves the arm away from the body’s midline, and reduced movement is a functional finding.','An electromyogram is a record of muscle electrical activity; electromyography is the recording process.'],'The report does not prove myositis, specify the severity of weakness, or provide the test result. A careful translation keeps symptoms, function, and testing separate.',[['Pain versus disease',['pain','cause','myalgia']],['Movement direction',['away','midline','abduction']],['Process versus record',['record','electromyograph','test']]]],[['Which injury usually involves a ligament?',['Sprain','Strain','Myalgia','Atrophy'],'A sprain concerns a ligament; a strain concerns muscle or tendon.'],['Which movement brings the top of the foot toward the shin?',['Dorsiflexion','Plantar flexion','Shoulder rotation','Forearm pronation'],'Dorsiflexion decreases the angle between the top of the foot and the lower leg.']]);

add('Cardiovascular, blood, and lymphatic language','A pulmonary artery carries blood toward the lungs with relatively little oxygen. It is still an artery. Vessel names depend on the direction of flow, showing why anatomy is more dependable than a memorized color.',[
 ['Follow blood through the circulation','Cardi/o refers to heart, angi/o to vessel, arteri/o to artery, and phleb/o or ven/o to vein. Arteries carry blood away from the heart and veins return it. Blood moves from systemic veins into the right atrium, through the right ventricle and pulmonary arteries to the lungs, then through pulmonary veins to the left atrium and ventricle before entering systemic arteries. Capillaries provide exchange between blood and tissues. Pulmonary vessels demonstrate that oxygen content does not define artery and vein. Endocardium is the inner heart lining, myocardium the muscular layer, and epicardium the outer surface layer. Pericardium is the enclosing sac. Prefixes help distinguish these locations, while -itis can identify inflammation of the named structure.'],
 ['Rate, rhythm, pressure, and perfusion','Tachycardia indicates a rapid heart rate and bradycardia a slow rate relative to context. An arrhythmia is an abnormal rhythm; a rapid rate can be regular or irregular. Hypertension means elevated blood pressure and hypotension reduced pressure. Ischemia means inadequate blood supply to tissue, while infarction is tissue death from prolonged ischemia. Angina describes a clinical chest-discomfort syndrome associated with myocardial ischemia, but chest pain in general has many causes. Palpitations are a person’s awareness of heartbeat, not a diagnosis of a specific arrhythmia. Perfusion is blood delivery to tissue and cannot be inferred perfectly from a single pressure reading. Distinguish a symptom, a measured variable, and an underlying disease process before interpreting a statement.'],
 ['Clots, vessels, and blood components','Thromb/o relates to a clot. A thrombus forms within circulation; an embolus travels and may obstruct a distant vessel. Not every embolus is a blood clot, although thromboemboli are common. Atherosclerosis involves plaque in arterial walls, while arteriosclerosis is a broader term for arterial thickening or loss of elasticity. Hemat/o and hem/o refer to blood. Erythr/o means red, leuk/o white, and thrombocyt/o platelet. Erythrocytes transport respiratory gases, leukocytes participate in immune functions, and platelets support hemostasis. Anemia concerns reduced oxygen-carrying capacity associated with hemoglobin or red-cell abnormalities, not the complete absence of blood. Leukocytosis means an increased white-cell count and does not independently identify a bacterial infection. Thrombocytopenia means a reduced platelet count.'],
 ['Lymphatic structures and immune vocabulary','Lymph is fluid moving through lymphatic vessels after collection from tissues. Lymph/o refers to lymph, lymphaden/o to lymph nodes, and splen/o to spleen. Lymph nodes filter lymph and support immune responses; the spleen filters blood and has immune and blood-cell functions. Lymphadenopathy means abnormal lymph nodes, often involving enlargement; lymphadenitis specifically indicates inflammation. Lymphedema is swelling related to impaired lymph drainage. Edema more broadly means excess interstitial fluid and has multiple mechanisms. Immun/o refers to immunity, and immunodeficiency means impaired immune capacity. Autoimmune processes involve responses against the body’s own components. Allergy is a particular immune response and should not be used as a generic label for any disliked food or medication side effect.'],
 ['Tests and specialties in a cardiovascular record','Electrocardiography records heart electrical activity; an electrocardiogram is the record. Echocardiography uses ultrasound to assess cardiac structures and function. Angiography produces images of vessels through a specified imaging technique, while venipuncture means puncturing a vein to obtain access or a specimen. A cardiologist specializes in heart-related disease, while a hematologist specializes in blood disorders. A complete blood count is a collection of measurements rather than one diagnosis. When a record says thrombocytopenia was found on a blood count, it reports a reduced platelet number; it does not state the cause or prove active bleeding. An accurate summary can preserve uncertainty: name the measured abnormality, identify the relevant component, and avoid adding an unreported mechanism.']
],[['Artery','A vessel carrying blood away from the heart. Oxygen content varies by circulation, so the pulmonary artery remains an artery despite carrying oxygen-poor blood.',0],['Vein','A vessel returning blood toward the heart. Pulmonary veins return oxygenated blood, showing why oxygen content is not the defining criterion.',0],['Myocardium','The muscular tissue of the heart wall. It differs from the inner lining and the surrounding pericardial sac.',0],['Ischemia','Inadequate blood supply to a tissue. It may be reversible or progress to injury; it is not automatically equivalent to completed infarction.',1],['Thrombus','A clot formed within a vessel or heart chamber. If material detaches and travels, the traveling material is an embolus.',1],['Thrombocytopenia','A reduced platelet count. The term identifies the affected blood component and direction of change, not the underlying cause.',1],['Lymphadenopathy','Abnormality of lymph nodes, often enlargement. It is broader than lymphadenitis and does not automatically establish infection or cancer.',1],['Electrocardiogram','A record of cardiac electrical activity. It is distinct from an ultrasound image and from the process called electrocardiography.',2]],['Explain why pulmonary arteries and pulmonary veins contradict the shortcut that arteries always carry oxygen-rich blood. Then distinguish an electrocardiogram from an echocardiogram.',['Arteries are defined by flow away from the heart, and veins by return toward it.','Pulmonary arteries take blood to the lungs before oxygenation; pulmonary veins return it after exchange.','An electrocardiogram records electrical activity, while an echocardiogram uses ultrasound to show cardiac structure and motion.'],'Use direction to classify vessels and the method to classify tests. Neither test name alone states the result or establishes a diagnosis.',[['Direction of vessels',['away','toward','return']],['Pulmonary oxygenation',['lungs','oxygen']],['Electrical versus ultrasound',['electrical','ultrasound']]]],[['Which term identifies tissue death after prolonged ischemia?',['Infarction','Palpitation','Bradycardia','Venipuncture'],'Infarction denotes tissue death associated with sustained loss of adequate blood supply.'],['Which organ filters blood rather than lymph?',['Spleen','Lymph node','Thoracic duct','Lymphatic capillary'],'The spleen has blood-filtering and immune functions.']]);

add('Word roots, suffixes, and the logic of a medical term','A procedure list contains gastrectomy, gastrotomy, and gastrostomy. The shared beginning points to the same organ, but the endings describe very different actions. Accurate decoding depends on preserving both pieces.',[
 ['The architecture of medical words','A root supplies a central meaning, often an organ or tissue: cardi refers to heart, gastr to stomach, neur to nerve, and oste to bone. A prefix, when present, modifies position, quantity, rate, or another feature. A suffix typically identifies a condition, procedure, or field. A combining vowel, commonly o, helps connect parts. A combining form is the root plus its combining vowel, such as cardi/o. These categories describe a word’s construction, not separate structures in the body. A term may contain more than one root, and many terms have no prefix. Never force every word into a three-part pattern. Some established words and names must be learned as complete entries. The HOSA blueprint gives word parts 45% of the written-test content, so this skill should support every system lesson that follows.'],
 ['Decode from the ending, then reconstruct meaning','Start with the suffix because it often establishes the category of meaning. In gastritis, -itis identifies inflammation and gastr identifies the stomach. In gastroscopy, -scopy identifies visual examination and gastr/o identifies the stomach. In gastroenteritis, gastr/o and enter identify stomach and intestine, while -itis still identifies inflammation. Translate the parts into a natural phrase rather than mechanically reading them in their printed order. Then check the established definition. A literal translation can be too broad: a term may have a specific accepted medical use that the roots alone do not reveal. Decoding is an efficient first hypothesis, not a license to invent a dictionary entry. After checking, practice the reverse task: produce the medical term from the plain-language definition. Recognition and accurate recall are different skills.'],
 ['Combining vowels are spelling tools','A combining vowel is often used between two roots, including when the second root starts with a vowel. Osteoarthritis retains the o between oste and arthr. A combining vowel is commonly omitted before a suffix beginning with a vowel, as gastr joins -itis in gastritis. It is commonly retained before a consonant-starting suffix, as gastr/o joins -scopy. These patterns explain many spellings but do not replace a reference for exceptions. Separate a learning slash from the final written word: cardi/o/logy is an analysis, while cardiology is the word you would submit. Read each term aloud, identify the stressed syllable in a dictionary, and write it from memory. In the current event, spelling matters in the written tiebreaker, so knowing what a word means is not enough if its letters are wrong.'],
 ['Procedure endings change the actual action','Three frequently confused endings are -ectomy, surgical removal; -otomy, incision into; and -ostomy, creation of an opening. A gastrectomy removes some or all stomach tissue. A gastrotomy opens the stomach by an incision. A gastrostomy creates an opening into the stomach, often to provide access. These words do not independently specify the exact extent, technique, indication, or postoperative outcome. Similarly, -plasty describes surgical repair or reconstruction, while -rrhaphy describes suturing. A procedure name should be kept separate from a diagnosis. Biopsy means obtaining material for examination; it does not mean cancer was found. When comparing answers, identify which part changes the action. This is more reliable than selecting the longest word or the word that looks most familiar.'],
 ['Turn word-part knowledge into precise interpretation','Build a study matrix with a root down one side and suffixes across the top. For each valid term, write its definition and one sentence showing its use. Do not create nonexistent terms simply because a root and suffix can be joined. Contrast related categories: cardiology is a discipline, cardiologist a professional, and cardiomegaly a finding. The -logist ending does not indicate a procedure, and -megaly does not automatically identify why an organ is enlarged. In a case question, translate only what the language supports. If a note says nephrectomy, you know that kidney tissue was surgically removed; you do not know the cause, side, or whether the removal was partial unless the record adds those facts. Precision includes recognizing missing information.']
],[['Root','The core meaning of a term, often identifying an organ or tissue. It can appear alone or with other roots; it does not necessarily state whether a disease or procedure is involved.',0],['Combining form','A root joined to a combining vowel, such as cardi/o. The vowel helps connect parts but usually does not add a separate anatomical meaning.',0],['-itis','A suffix indicating inflammation. Inflammation can have infectious or noninfectious causes, so this ending alone does not establish that bacteria are present.',1],['-ectomy','Surgical removal of a structure or part of it. The full clinical record must specify extent; the suffix alone does not guarantee removal of the entire organ.',2],['-otomy','An incision into a structure. An incision is different from removing the structure or creating an opening intended to provide ongoing access.',2],['-ostomy','Creation of a surgical opening. The complete term identifies the structure involved, while other documentation explains purpose and technique.',2],['-scopy','Visual examination using an instrument. The procedure name describes examination rather than proving the result or diagnosis found during it.',2],['-megaly','Enlargement of an organ or structure. It describes a finding, and additional assessment is needed to determine the cause and clinical importance.',1]],['Translate gastrectomy, gastrotomy, and gastrostomy for a learner, and explain why replacing one with another changes the record.',['All three terms identify the stomach through gastr.','The endings indicate removal, incision, and creation of an opening respectively.','The term alone does not specify the reason, exact extent, or outcome of the procedure.'],'A correct translation preserves the shared organ and the different actions. The similar spelling makes careful suffix identification especially important.',[['Identifies shared organ',['gastr','stomach']],['Distinguishes the three actions',['removal','incision','opening']],['Recognizes limits of the label',['extent','reason','outcome','not']]]],[['Which suffix indicates suturing?',['-rrhaphy','-ectomy','-megaly','-logy'],'-rrhaphy refers to suturing; the other suffixes describe removal, enlargement, and study.'],['What should follow a literal word-part translation?',['Check the established medical definition','Assume every possible combination is valid','Infer the patient’s treatment','Ignore spelling'],'Word parts are a decoding tool, but established definitions and spelling remain authoritative.']],{t:'w',kind:'wordbuild',title:'Build three procedure names',parts:{prefix:[],root:[['gastr','stomach'],['gastr/o','stomach combining form']],suffix:[['ectomy','removal'],['tomy','incision'],['stomy','created opening']]},targets:[['Removal of stomach tissue',['','gastr','ectomy'],'gastrectomy'],['Incision into the stomach',['','gastr/o','tomy'],'gastrotomy'],['Creation of a stomach opening',['','gastr/o','stomy'],'gastrostomy']]});

add('Prefixes, opposites, plurals, and spelling traps','Hypoglycemia and hyperglycemia differ by only a few letters. Those letters reverse the direction of the finding. A precise reader pays attention to modifiers before deciding what the term means.',[
 ['Prefixes add direction and scale','Hyper- indicates excessive or above a reference level, while hypo- indicates below or deficient. Tachy- describes rapid and brady- slow. Poly- indicates many or much; oligo- indicates few or scanty. A- or an- can indicate absence, but not every word beginning with those letters contains that prefix. Dys- can mean difficult, painful, or abnormal, while eu- means normal or good. Learn prefixes in contrasting pairs and attach them to a known root. Tachypnea and bradypnea modify breathing rate, whereas tachycardia and bradycardia modify heart rate. The same prefix changes a different variable depending on the root. A term’s direction does not quantify its severity. Hyperglycemia means elevated blood glucose, but a specific value and clinical context are needed to judge its significance.'],
 ['Position and relationship prefixes','Intra- means within, inter- between, peri- around, and endo- within or inner. Sub- means under and supra- above; epi- can mean upon or over. Trans- means across, and retro- behind or backward. An intramuscular route involves delivery within muscle, while an intercostal location lies between ribs. Pericardium is the sac around the heart; endocardium is its inner lining. Do not interpret every peri- term as a membrane, because the prefix gives a relationship rather than a universal structure type. Ante- usually means before, while anti- means against. Prenatal and postnatal describe timing around birth. A helpful practice is to draw the reference structure and place the named item relative to it, making the prefix visible in space or time.'],
 ['Similar spelling can name different anatomy','Ileum is the distal portion of the small intestine; ilium is a large part of the hip bone. Ureter is the tube from kidney to bladder; urethra leads from bladder toward the exterior. Myel/o can refer to spinal cord or bone marrow depending on the term, so context determines the correct expansion. Cervic/o can refer to neck or uterine cervix. These ambiguities show why word recognition must be tied to a body system. Compare an established sentence rather than memorizing a fragment in isolation. A clinician discussing cervical vertebrae is discussing the neck, while cervical screening may refer to the uterine cervix. If the context does not resolve a meaning, acknowledge uncertainty instead of selecting the first definition in memory.'],
 ['Plural patterns and pronunciation','Medical plurals reflect several language traditions. Vertebra becomes vertebrae, diagnosis becomes diagnoses, bacterium becomes bacteria, and bronchus becomes bronchi. Some accepted terms also have ordinary English plurals, and usage can vary by reference. Use the event’s official dictionaries and textbooks to settle a spelling question. A pronunciation guide separates syllables and marks stress; it is not a substitute for the word’s letters. Silent letters, doubled consonants, and vowel changes require deliberate retrieval practice. Write a definition, close the reference, then spell the term. Check immediately and record the specific error, such as confusing -rrhea with -rhea. Copying a word repeatedly without retrieving it can create familiarity while leaving recall weak. The written tiebreaker rewards correctly produced language, not just recognition.'],
 ['Abbreviations and cautious expansion','Abbreviations compress information but can have multiple meanings across specialties. A familiar abbreviation should never be expanded without considering its context. A medication-related abbreviation may be discouraged because it resembles another symbol; terminology study is not permission to introduce it into documentation. Write full terms when learning the concept, then learn accepted abbreviations separately. Compare a word’s literal construction with its actual clinical definition: anemia does not mean that a person has no blood at all. It concerns reduced oxygen-carrying capacity associated with red-cell or hemoglobin abnormalities. This is a useful example of why prefixes provide clues without replacing a full definition. On an exam, eliminate an answer only after checking the complete word; a familiar ending cannot rescue a contradictory prefix.']
],[['Hyper-','Above a usual or reference level, or excessive. It gives a direction but does not specify the numerical degree or clinical cause of the abnormality.',0],['Hypo-','Below a usual or reference level, or deficient. It contrasts with hyper- and must be linked to the variable named by the rest of the word.',0],['Inter-','Between structures, as in intercostal. This is distinct from intra-, which places something within a structure rather than between separate ones.',0],['Peri-','Around a structure. Pericardium surrounds the heart, but the prefix alone does not say whether the named structure is healthy or diseased.',0],['Dys-','Difficult, painful, or abnormal. The exact meaning depends on the complete word, as in dysphagia for difficulty swallowing and dysuria for painful or difficult urination.',0],['Ileum','A segment of small intestine. It is anatomically unrelated to the ilium despite the close spelling, so the body-system context is essential.',0],['Ilium','A major part of the hip bone. Confusing it with ileum would move the description from the skeleton to the digestive tract.',0],['Diagnoses','The plural of diagnosis. The ending changes according to an established language pattern; accurate spelling is part of correctly communicating the term.',1]],['A student translates hyperglycemia as low blood sugar, intramuscular as between muscles, and ileum as a pelvic bone. Correct all three and explain the strategy that reveals each error.',['Hyper- means high, so hyperglycemia concerns elevated blood glucose.','Intra- means within; between would require inter-.','Ileum is intestine, while ilium is the pelvic bone.'],'Check the modifying prefix, then the root and body-system context. Similar appearance is not enough to establish meaning, and the translated terms do not independently determine treatment.',[['Corrects direction',['high','elevated','hyper']],['Corrects spatial relation',['within','intra','between']],['Distinguishes spelling and anatomy',['ileum','ilium','intestin','bone']]]],[['Which pair concerns speed?',['Tachy- and brady-','Peri- and endo-','Supra- and sub-','Ante- and post-'],'Tachy- and brady- describe rapid and slow rates.'],['Which is the plural of bacterium?',['Bacteria','Bacteriums only','Bacteriae','Bacterioses'],'Bacteria is the established plural of bacterium.']]);

add('Anatomical position, body planes, cavities, and organization','A note describes a lesion on the anterior left forearm. Turning the patient over does not move the lesion to a new anatomical side. Standard orientation lets different observers describe the same location.',[
 ['One reference position','Anatomical position describes a person upright, facing forward, with the upper limbs at the sides and palms facing forward. Directional terms refer to this shared reference, even when a person is sitting, prone, or supine. Right and left belong to the patient, not the observer. Anterior means toward the front; posterior toward the back. Superior means toward the head and inferior toward the feet. Medial means toward the midline, while lateral means away from it. These terms express relationships. A structure can be medial to one neighbor and lateral to another. Avoid statements such as the arm is lateral without identifying the comparison when precision matters. The sternum is anterior to the heart, and the heart is medial to the lungs.'],
 ['Limbs, depth, and movements between views','Proximal means nearer the attachment or origin of a structure, and distal farther from it. The elbow is proximal to the wrist; the fingers are distal to the elbow. These words are especially useful when ordinary above and below would change with body position. Superficial means nearer the surface; deep means farther from it. The skin is superficial to skeletal muscle. Supine means lying face upward, while prone means face downward. Ipsilateral means on the same side and contralateral on the opposite side. Bilateral concerns both sides. Learn these by drawing pairs of landmarks. A sentence about a contralateral response requires two reference locations; without them, the relationship is incomplete. The vocabulary supports examination and imaging, but does not by itself explain disease.'],
 ['Planes are imagined sections','A sagittal plane divides right and left portions; a midsagittal plane passes through the midline to create equal halves. A frontal or coronal plane divides anterior and posterior portions. A transverse or horizontal plane divides superior and inferior portions. An oblique section crosses at an angle. Planes are not cavities or organs; they are ways to describe a cut or image. A transverse image of the abdomen may show several organs at the same level, while a sagittal image follows a front-to-back vertical slice. When interpreting a picture, use the orientation labels rather than assuming the image’s left side is the patient’s left. Distinguish the plane of the image from the direction of a structure visible within it. A structure may extend through multiple planes.'],
 ['Cavities and membranes','The dorsal body cavity includes the cranial cavity and vertebral canal, protecting brain and spinal cord. The ventral cavity includes thoracic and abdominopelvic divisions. The diaphragm separates thoracic and abdominal regions. Pleural cavities are associated with the lungs, while the pericardial cavity surrounds the heart within the mediastinum. The abdominal and pelvic regions are continuous rather than separated by a solid diaphragm. Serous membranes have parietal layers lining cavity walls and visceral layers covering organs, with a thin lubricating fluid between them. Retroperitoneal structures lie behind the peritoneal lining. A kidney’s location therefore differs from a structure suspended within the peritoneal cavity. These terms explain relationships and coverings; they should not be mistaken for the names of the organ tissue itself.'],
 ['From cells to regions','Cells form tissues; tissues combine into organs; organs work in systems. Cytology studies cells and histology studies tissues. An organ such as the stomach contains multiple tissue types, so organ and tissue are not synonyms. Regional names provide additional precision: brachial concerns upper arm, antebrachial forearm, carpal wrist, femoral thigh, patellar anterior knee, popliteal posterior knee, and plantar sole. Abdominal quadrants and nine-region schemes are different mapping systems. The right upper quadrant can include part of the liver but does not equal the liver alone. Pain in a region does not prove that the organ beneath it is the source. Referred pain and overlapping anatomy make careful assessment necessary. In terminology questions, distinguish a location label from a diagnostic conclusion.']
],[['Medial','Toward the body’s midline relative to another structure. A relationship can change depending on which two structures are being compared.',0],['Distal','Farther from a limb’s attachment or a structure’s point of origin. It stays meaningful even when the limb is raised or rotated.',0],['Sagittal plane','An imagined division into right and left portions. Only a midsagittal plane necessarily creates equal right and left halves.',0],['Frontal plane','An imagined division into anterior and posterior portions. Coronal is another name for this orientation.',0],['Transverse plane','An imagined division into superior and inferior portions. It is commonly associated with cross-sectional views.',0],['Visceral layer','The serous membrane layer directly associated with the organ surface, contrasting with the parietal layer at the cavity wall.',0],['Histology','Study of tissue structure. It differs from cytology, which focuses on cells, and from gross anatomy, which studies larger visible structures.',2],['Retroperitoneal','Located behind the peritoneal lining. The term indicates an anatomical relationship rather than a disease or surgical procedure.',0]],['Explain the meaning of a superficial lesion on the anterior left antebrachial region, and compare a transverse view with a sagittal view of that area.',['Left is the patient’s left, and antebrachial means forearm.','Anterior refers to the front in anatomical position; superficial means near the surface.','Transverse divides upper and lower portions, while sagittal divides right and left portions.'],'The description locates the lesion precisely but does not establish its cause, depth in millimeters, or treatment. Orientation remains anchored to anatomical position even if the patient changes posture.',[['Identifies patient orientation',['patient','left','anterior']],['Explains region and depth',['forearm','superficial','surface']],['Distinguishes planes',['transverse','sagittal','right','inferior']]]],[['The wrist is which relative to the elbow?',['Distal','Proximal','Medial by definition','Superior in every position'],'The wrist lies farther from the limb’s attachment.'],['Which term means lying face upward?',['Supine','Prone','Ipsilateral','Oblique'],'Supine describes face-up position; prone describes face-down position.']]);
